{
  "candidates": [
    {
      "explanation": "Node0 has backlog and low inventory; boost order to replenish. Node1 has ample inventory and pipeline; reduce order to avoid excess. Node2 has low pipeline; increase order to build buffer.",
      "rules": [
        {
          "when": "agent==0 and backlog>0",
          "delta": "min(6, backlog)"
        },
        {
          "when": "agent==1 and inventory>10 and pipeline>10",
          "delta": "-3"
        },
        {
          "when": "agent==2 and pipeline<5",
          "delta": "4"
        }
      ]
    },
    {
      "explanation": "Node0: if backlog, order more; else if inventory low, order more. Node1: if backlog, order more; else if inventory high, order less. Node2: if backlog, order more; else if pipeline low, order more.",
      "rules": [
        {
          "when": "agent==0 and backlog>0",
          "delta": "min(6, backlog)"
        },
        {
          "when": "agent==0 and inventory<5",
          "delta": "2"
        },
        {
          "when": "agent==1 and backlog>0",
          "delta": "min(6, backlog)"
        },
        {
          "when": "agent==1 and inventory>10",
          "delta": "-2"
        }
      ]
    },
